// Curated on-theme icon catalog. Each entry is "prefix:slug". Every
// entry has been pre-flight verified offline (sharp rasterisation at
// 300x300 / density 150, dark-pixel ratio inside [0.015, 0.97]) so the
// runtime never has to discover broken slugs. Each keyword holds 1000
// working entries — a 2x buffer above the 500-maze book size so even ~50%
// browser-side rasterisation failures still leave 500+ working unique picks.

